for i,(slug,title,desc,external,label,schedule,sections) in enumerate(POSTS):
    path=f'/blog/{slug}/'
    body=T.page_header(h1=title,subtitle=desc,trail=[('Home','/'),('Blog','/blog/'),(title,path)])
    notice=f' AE’s publication schedule lists this companion Medium article for {schedule}; its link may not resolve before publication.' if schedule else ''
    body+=f'<section class="content-section"><div class="container narrow"><p>By AE Tax Advisors Team | Published November 6, 2026</p><p>This original AE Tax Advisors guide accompanies <a href="{external}">{label}</a>.{notice}</p></div></section>'
    for h,*paras in sections:
        body+='<section class="content-section"><div class="container narrow"><h2>'+h+'</h2>'+''.join('<p>'+p+'</p>' for p in paras)+'</div></section>'
    body+='<section class="content-section"><div class="container narrow"><h2>More from AE Tax Advisors</h2><p>Explore the <a href="https://medium.com/@AE_Tax_Advisors">AE Tax Advisors Medium profile</a> and these related planning guides:</p><ul>'
    body+=''.join(f'<li><a href="/blog/{p[0]}/">{p[1]}</a></li>' for p in POSTS if p[0]!=slug)
    body+='</ul><h2>Primary sources and further reading</h2><ul>'+''.join(f'<li><a href="{u}">{n}</a></li>' for u,n in SOURCES[i])+'</ul><p>General educational information. Tax treatment depends on the applicable year, jurisdiction and individual facts. Review eligibility and implementation with your tax professional.</p></div></section>'
    schema=T.article_schema(title=title,description=desc,url=T.SITE+path,published=DATE,modified=DATE,citations=[u for u,n in SOURCES[i]])
    schema['isPartOf']={'@type':'Blog','@id':T.SITE+'/blog/','name':'AE Tax Advisors Blog'}
    dest=Path('.'+path);dest.mkdir(parents=True,exist_ok=True)
    (dest/'index.html').write_text(T.build_page(title=title+' | AE Tax Advisors',description=desc,path=path,body=body,schemas=[schema,T.breadcrumb_schema([('Home','/'),('Blog','/blog/'),(title,path)])],published=DATE,modified=DATE,active_nav='/blog/'))
print('Created',len(POSTS),'companion articles')
# Update only these entries, preserving existing sitemap metadata.
for name in ['sitemap.xml','sitemap-blog.xml']:
    p=Path(name);s=p.read_text()
    for post in POSTS:
        url=T.SITE+'/blog/'+post[0]+'/'
        if '<loc>'+url+'</loc>' not in s:
            s=s.replace('</urlset>',f'  <url><loc>{url}</loc><lastmod>{DATE}</lastmod></url>\n</urlset>')
    p.write_text(s)

