block+=''.join(f'<li><a href="/blog/{p[0]}/">{p[1]}</a></li>' for p in POSTS)
block+='</ul></div></section>'+end
s=s.replace('<main id="main-content" tabindex="-1">','<main id="main-content" tabindex="-1">'+block,1)
